def call(self, x, training=False):
   y = super().call(x)
   if training:
      constraint_0 = K.sum(K.square(y), axis=(1, 2)) - 1
      constraint_1 = K.sum(y, axis=(1, 2))
      return y, constraint_0, constraint_1
   else:
      return y
